import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

interface LitigationModuleProps {
  category: LitigationCategory;
  status: LitigationStatus;
}

const LitigationModule: React.FC<LitigationModuleProps> = ({ category, status }) => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      // Filter records for this specific page view
      setRecords(recs.filter(r => r.category === category && r.status === status));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRecord?.clientId || !selectedRecord?.referenceNo) {
      alert("Please select a client and enter a Reference Number.");
      return;
    }

    const client = clients.find(c => c.id === selectedRecord.clientId);
    await mockBackend.saveLitigationRecord({
      ...selectedRecord,
      clientName: client?.legalName || 'Unknown',
      category,
      status
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this litigation record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    return records.filter(r => 
      r.clientName.toLowerCase().includes(s) || 
      r.referenceNo.toLowerCase().includes(s) ||
      (r.officerName || '').toLowerCase().includes(s)
    );
  }, [records, search]);

  const statusColors = {
    Pending: 'bg-amber-100 text-amber-700',
    Filed: 'bg-indigo-100 text-indigo-700',
    Drop: 'bg-green-100 text-green-700',
    Demand: 'bg-red-100 text-red-700'
  };

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4">

      {/* Dynamic Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{category}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{status}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">In View</p>
            <p className="text-xl font-black text-indigo-600 leading-none">{filteredRecords.length}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search client name or reference no..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button 
          onClick={() => { setSelectedRecord({ status, category }); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 whitespace-nowrap shrink-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add {category} Record
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1000px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[250px]">Entity / Reference</th>
                <th className="px-8 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Section / Officer</th>
                <th className="px-8 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Timelines</th>
                <th className="px-8 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[150px]">Liability</th>
                <th className="px-8 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-right w-[150px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr>
                  <td colSpan={5} className="py-32 text-center">
                    <p className="text-sm font-black uppercase tracking-[0.2em] text-slate-300">No {status.toLowerCase()} records found for {category}</p>
                  </td>
                </tr>
              ) : (
                filteredRecords.map(rec => (
                  <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                    <td className="px-8 py-6">
                      <p className="text-sm font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</p>
                      <p className="text-[10px] font-black text-indigo-600 uppercase tracking-tighter mt-1">{rec.referenceNo}</p>
                    </td>
                    <td className="px-8 py-6">
                       <p className="text-[11px] font-black text-slate-600 uppercase">{rec.section || '---'}</p>
                       <p className="text-[10px] font-bold text-slate-400 truncate mt-0.5">{rec.officerName || 'Unknown Officer'}</p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-1.5"><div className="h-1 w-1 rounded-full bg-slate-300"/><span className="text-[10px] font-black text-slate-400 uppercase">Iss: {rec.issuedDate}</span></div>
                        <div className="flex items-center gap-1.5"><div className="h-1 w-1 rounded-full bg-red-400 animate-pulse"/><span className="text-[10px] font-black text-red-500 uppercase">Due: {rec.dueDate}</span></div>
                        {rec.filedDate && <div className="flex items-center gap-1.5"><div className="h-1 w-1 rounded-full bg-indigo-400"/><span className="text-[10px] font-black text-indigo-600 uppercase">Fld: {rec.filedDate}</span></div>}
                      </div>
                    </td>
                    <td className="px-8 py-6">
                       <p className="text-sm font-black text-slate-900 leading-none">₹{rec.amountInvolved?.toLocaleString() || '0'}</p>
                       <span className={`inline-block mt-2 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${statusColors[rec.status]}`}>{rec.status}</span>
                    </td>
                    <td className="px-8 py-6 text-right">
                       <div className="flex items-center justify-end gap-2">
                          <button 
                            onClick={() => { setSelectedRecord(rec); setIsModalOpen(true); }}
                            className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center"
                          >
                             <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                          </button>
                          <button 
                            onClick={() => handleDelete(rec.id)}
                            className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-red-600 hover:bg-white transition-all flex items-center justify-center opacity-0 group-hover:opacity-100"
                          >
                             <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                       </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
