              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Ref No (SCN/APL)</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.referenceNo || ''} onChange={e => setSelectedRecord({...selectedRecord, referenceNo: e.target.value.toUpperCase()})} placeholder="e.g. SCN/001/25" />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Legal Section</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.section || ''} onChange={e => setSelectedRecord({...selectedRecord, section: e.target.value.toUpperCase()})} placeholder="e.g. SEC 73" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Date of Issue</label>
                  <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.issuedDate || ''} onChange={e => setSelectedRecord({...selectedRecord, issuedDate: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Final Deadline</label>
                  <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.dueDate || ''} onChange={e => setSelectedRecord({...selectedRecord, dueDate: e.target.value})} />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Officer Name</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.officerName || ''} onChange={e => setSelectedRecord({...selectedRecord, officerName: e.target.value})} placeholder="Adjudicating Officer" />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Liability Amount (₹)</label>
                  <input type="number" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.amountInvolved || ''} onChange={e => setSelectedRecord({...selectedRecord, amountInvolved: Number(e.target.value)})} placeholder="0.00" />
                </div>
              </div>

              {status === 'Filed' && (
                <div className="animate-in fade-in slide-in-from-top-2">
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Submission Date</label>
                   <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.filedDate || ''} onChange={e => setSelectedRecord({...selectedRecord, filedDate: e.target.value})} />
                </div>
              )}

              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Internal Remarks</label>
                <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20 focus:ring-4 focus:ring-indigo-100 transition-all"
                  value={selectedRecord?.remarks || ''} onChange={e => setSelectedRecord({...selectedRecord, remarks: e.target.value})} placeholder="Add staff notes or progress updates..." />
              </div>
            </div>

            <div className="flex gap-4 pt-4">
              <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
              <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all">
                {selectedRecord?.id ? 'Update Record' : 'Commit to Suite'}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

