import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

interface LitigationModuleProps {
  category: LitigationCategory;
  status: LitigationStatus;
}

const LitigationModule: React.FC<LitigationModuleProps> = ({ category, status }) => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  // Column Specific Filters
  const [sectionFilter, setSectionFilter] = useState('All');
  const [daysLeftFilter, setDaysLeftFilter] = useState<'All' | 'Critical' | 'Healthy'>('All');
  const [replyStatusFilter, setReplyStatusFilter] = useState<'All' | 'Pending' | 'Overdue' | 'Filed'>('All');

  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'section' | 'days' | 'reply' | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      // Filter records for this specific page view
      setRecords(recs.filter(r => r.category === category && r.status === status));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRecord?.clientId || !selectedRecord?.referenceNo) {
      alert("Please select a client and enter a Reference Number.");
      return;
    }

    const client = clients.find(c => c.id === selectedRecord.clientId);
    await mockBackend.saveLitigationRecord({
      ...selectedRecord,
      clientName: client?.tradeName || client?.legalName || 'Unknown',
      category,
      status
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this litigation record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate).getTime();
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due - now.getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  const sections = useMemo(() => {
    const s = new Set<string>();
    records.forEach(r => { if (r.section) s.add(r.section); });
    return Array.from(s).sort();
  }, [records]);

  const sectionCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    records.forEach(r => {
      const sec = r.section || 'N/A';
      counts[sec] = (counts[sec] || 0) + 1;
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [records]);

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    let list = records.filter(r => 
      r.clientName.toLowerCase().includes(s) || 
      r.referenceNo.toLowerCase().includes(s) ||
      (r.gstProfile?.gstin || '').toLowerCase().includes(s)
    );

    if (sectionFilter !== 'All') {
      list = list.filter(r => r.section === sectionFilter);
    }

    if (daysLeftFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        return daysLeftFilter === 'Critical' ? dl <= 7 : dl > 7;
      });
    }

    if (replyStatusFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        const isFiled = r.status === 'Filed';
        const isOverdue = r.status === 'Pending' && dl < 0;
        const isPending = r.status === 'Pending' && dl >= 0;

        if (replyStatusFilter === 'Filed') return isFiled;
        if (replyStatusFilter === 'Overdue') return isOverdue;
        if (replyStatusFilter === 'Pending') return isPending;
        return true;
      });
    }

    return list;
  }, [records, search, sectionFilter, daysLeftFilter, replyStatusFilter]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4">

      {/* Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total {category}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>

          <div className="flex items-center gap-4 border-l border-slate-100 pl-6 overflow-x-auto no-scrollbar max-w-[400px]">
            {sectionCounts.map(([sec, count]) => (
              <div key={sec} className="text-center shrink-0">
                <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">U/s {sec}</p>
                <p className="text-sm font-black text-indigo-600 leading-none">{count}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search Trade Name, GSTIN or Ref No..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button 
          onClick={() => { setSelectedRecord({ status, category, taxPeriod: '' }); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 whitespace-nowrap shrink-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add Record
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1400px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px]">GSTIN</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px] relative">
                  <div className="flex items-center gap-1">
                    Notice U/s
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'section' ? null : 'section')} className="p-1 hover:bg-white rounded transition-colors">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'section' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1">
                      <button onClick={() => { setSectionFilter('All'); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === 'All' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>All Sections</button>
                      {sections.map(s => (
                        <button key={s} onClick={() => { setSectionFilter(s); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === s ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>Sec {s}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Tax Period</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Notice Date</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Due Date</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px] relative">
                  <div className="flex items-center gap-1">
                    Days Left
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'days' ? null : 'days')} className="p-1 hover:bg-white rounded transition-colors">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'days' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1">
                      {['All', 'Critical', 'Healthy'].map(opt => (
                        <button key={opt} onClick={() => { setDaysLeftFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${daysLeftFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px] relative">
                  <div className="flex items-center gap-1">
                    Reply Status
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'reply' ? null : 'reply')} className="p-1 hover:bg-white rounded transition-colors">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'reply' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1">
                      {['All', 'Pending', 'Overdue', 'Filed'].map(opt => (
                        <button key={opt} onClick={() => { setReplyStatusFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${replyStatusFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Remark</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr>
                  <td colSpan={11} className="py-32 text-center">
                    <p className="text-sm font-black uppercase tracking-[0.2em] text-slate-300">No matching records found</p>
                  </td>
                </tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const dl = getDaysLeft(rec.dueDate);
                  const client = clients.find(c => c.id === rec.clientId);
                  const isFiled = rec.status === 'Filed';
                  const isOverdue = rec.status === 'Pending' && dl < 0;

                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                      <td className="px-4 py-5 text-[10px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5">
                        <p className="text-[11px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</p>
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-indigo-600 font-mono tracking-widest">
                        {client?.gstProfile?.gstin || 'N/A'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-600 uppercase">
                        {rec.section ? `U/s ${rec.section}` : '---'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-700 uppercase">
                        {rec.taxPeriod || '---'}
                      </td>
                      <td className="px-4 py-5 text-[10px] font-black text-slate-500 uppercase">
                        {rec.issuedDate}
                      </td>
                      <td className="px-4 py-5 text-[10px] font-black text-slate-500 uppercase">
                        {rec.dueDate}
                      </td>
                      <td className="px-4 py-5">
                         {isFiled ? (
                           <span className="text-[10px] font-black text-emerald-500 uppercase">Completed</span>
                         ) : (
                           <div className="flex items-center gap-1.5">
                             <div className={`h-1.5 w-1.5 rounded-full ${dl <= 7 ? 'bg-red-500 animate-pulse' : 'bg-amber-400'}`} />
                             <span className={`text-[11px] font-black ${dl <= 7 ? 'text-red-500' : 'text-slate-700'}`}>
                               {dl < 0 ? `${Math.abs(dl)} days overdue` : `${dl} days left`}
                             </span>
                           </div>
                         )}
                      </td>
                      <td className="px-4 py-5 text-center">
                         <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                           isFiled ? 'bg-emerald-100 text-emerald-700' :
                           isOverdue ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                         }`}>
                           {isFiled ? 'Filed' : isOverdue ? 'Overdue' : 'Pending'}
                         </span>
                      </td>
                      <td className="px-4 py-5">
                        <p className="text-[10px] font-medium text-slate-500 truncate italic" title={rec.remarks}>{rec.remarks || '---'}</p>
                      </td>
                      <td className="px-4 py-5 text-right">
                         <div className="flex items-center justify-end gap-2">
                            <button 
                              onClick={() => { setSelectedRecord(rec); setIsModalOpen(true); }}
                              className="h-7 w-7 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center"
                            >
                               <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                            </button>
                            <button 
                              onClick={() => handleDelete(rec.id)}
                              className="h-7 w-7 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-red-600 hover:bg-white transition-all flex items-center justify-center opacity-0 group-hover:opacity-100"
                            >
                               <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            </button>
                         </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <form onSubmit={handleSave} className="w-full max-w-lg bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
            <div className="flex items-center justify-between">
               <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">
                 {selectedRecord?.id ? 'Update' : 'New'} Record
               </h3>
               <button type="button" onClick={() => setIsModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors">
                  <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
               </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Entity Selection</label>
                <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                  value={selectedRecord?.clientId || ''} onChange={e => setSelectedRecord({...selectedRecord, clientId: e.target.value})}>
                  <option value="">Select Entity</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.tradeName || c.legalName}</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Ref No (SCN/APL)</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.referenceNo || ''} onChange={e => setSelectedRecord({...selectedRecord, referenceNo: e.target.value.toUpperCase()})} placeholder="e.g. SCN/001/25" />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Legal Section (U/s)</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.section || ''} onChange={e => setSelectedRecord({...selectedRecord, section: e.target.value.toUpperCase()})} placeholder="e.g. 61" />
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Tax Period</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                  value={selectedRecord?.taxPeriod || ''} onChange={e => setSelectedRecord({...selectedRecord, taxPeriod: e.target.value.toUpperCase()})} placeholder="e.g. APR-23 TO MAR-24" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Notice Date</label>
                  <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.issuedDate || ''} onChange={e => setSelectedRecord({...selectedRecord, issuedDate: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Final Deadline</label>
                  <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.dueDate || ''} onChange={e => setSelectedRecord({...selectedRecord, dueDate: e.target.value})} />
                </div>
              </div>

              {category !== 'Notice' && (
                <div className="grid grid-cols-2 gap-4 animate-in fade-in">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Officer Name</label>
                    <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                      value={selectedRecord?.officerName || ''} onChange={e => setSelectedRecord({...selectedRecord, officerName: e.target.value})} placeholder="Adjudicating Officer" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Liability Amount (₹)</label>
                    <input type="number" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                      value={selectedRecord?.amountInvolved || ''} onChange={e => setSelectedRecord({...selectedRecord, amountInvolved: Number(e.target.value)})} placeholder="0.00" />
                  </div>
                </div>
              )}

              {status === 'Filed' && (
                <div className="animate-in fade-in slide-in-from-top-2">
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Submission Date</label>
                   <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                    value={selectedRecord?.filedDate || ''} onChange={e => setSelectedRecord({...selectedRecord, filedDate: e.target.value})} />
                </div>
              )}

              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Internal Remarks</label>
                <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20 focus:ring-4 focus:ring-indigo-100 transition-all"
                  value={selectedRecord?.remarks || ''} onChange={e => setSelectedRecord({...selectedRecord, remarks: e.target.value})} placeholder="Add staff notes or progress updates..." />
              </div>
            </div>

            <div className="flex gap-4 pt-4">
              <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
              <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all">
                {selectedRecord?.id ? 'Update Record' : 'Commit to Suite'}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default LitigationModule;

import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';

interface LitigationModuleProps {
  category: LitigationCategory;
  status: LitigationStatus;
}

const LitigationModule: React.FC<LitigationModuleProps> = ({ category, status }) => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  // Column Specific Filters
  const [sectionFilter, setSectionFilter] = useState('All');
  const [daysLeftFilter, setDaysLeftFilter] = useState<'All' | 'Critical' | 'Healthy'>('All');
  const [replyStatusFilter, setReplyStatusFilter] = useState<'All' | 'Pending' | 'Overdue' | 'Filed'>('All');

  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'section' | 'days' | 'reply' | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      // Filter records for this specific page view
      setRecords(recs.filter(r => r.category === category && r.status === status));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRecord?.clientId || !selectedRecord?.referenceNo) {
      alert("Please select a client and enter a Reference Number.");
      return;
    }

    const client = clients.find(c => c.id === selectedRecord.clientId);
    await mockBackend.saveLitigationRecord({
      ...selectedRecord,
      clientName: client?.tradeName || client?.legalName || 'Unknown',
      category,
      status
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this litigation record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate).getTime();
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due - now.getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  const sections = useMemo(() => {
    const s = new Set<string>();
    records.forEach(r => { if (r.section) s.add(r.section); });
    return Array.from(s).sort();
  }, [records]);

  const sectionCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    records.forEach(r => {
      const sec = r.section || 'N/A';
      counts[sec] = (counts[sec] || 0) + 1;
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [records]);

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    // Fix: Corrected filter to search across client record GSTIN via cross-reference
    let list = records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return r.clientName.toLowerCase().includes(s) || 
             r.referenceNo.toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });

    if (sectionFilter !== 'All') {
      list = list.filter(r => r.section === sectionFilter);
    }

    if (daysLeftFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        return daysLeftFilter === 'Critical' ? dl <= 7 : dl > 7;
      });
    }

    if (replyStatusFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        const isFiled = r.status === 'Filed';
        const isOverdue = r.status === 'Pending' && dl < 0;
        const isPending = r.status === 'Pending' && dl >= 0;

        if (replyStatusFilter === 'Filed') return isFiled;
        if (replyStatusFilter === 'Overdue') return isOverdue;
        if (replyStatusFilter === 'Pending') return isPending;
        return true;
      });
    }

    return list;
  }, [records, clients, search, sectionFilter, daysLeftFilter, replyStatusFilter]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4">

      {/* Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total {category}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>

