                <tr><td colSpan={11} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No matching records</td></tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const dl = getDaysLeft(rec.dueDate);
                  const client = clients.find(c => c.id === rec.clientId);
                  const isOverdue = rec.status === 'Pending' && dl < 0;
                  const isCritical = rec.status === 'Pending' && dl <= 7 && dl >= 0;

                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                      <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client?.gstProfile?.gstin || 'N/A'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-600 uppercase">{rec.section ? `Sec ${rec.section}` : '---'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-700 uppercase">{rec.taxPeriod || '---'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{rec.issuedDate}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{rec.dueDate}</td>
