              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Internal Remarks</label>
                <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20 focus:ring-4 focus:ring-indigo-100 transition-all"
                  value={selectedRecord?.remarks || ''} onChange={e => setSelectedRecord({...selectedRecord, remarks: e.target.value})} placeholder="Add staff notes or progress updates..." />
              </div>
            </div>

            <div className="flex gap-4 pt-4">
              <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
              <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all">
                {selectedRecord?.id ? 'Update Record' : 'Commit to Vault'}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default LitigationModule;

import React, { useState, useMemo } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';

interface NoticeFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: Partial<LitigationRecord>) => void;
  clients: Client[];
  category: LitigationCategory;
  initialData?: Partial<LitigationRecord> | null;
}

const NoticeForm: React.FC<NoticeFormProps> = ({ isOpen, onClose, onSave, clients, category, initialData }) => {
  const [formData, setFormData] = useState<Partial<LitigationRecord>>(initialData || {
    status: 'Pending',
    category: category,
    taxPeriod: '',
    section: '',
    referenceNo: '',
    issuedDate: '',
    dueDate: '',
    remarks: ''
  });

  const [searchQuery, setSearchQuery] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  const filteredClients = useMemo(() => {
    const s = searchQuery.toLowerCase();
    if (!s) return [];
    return clients.filter(c => 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );
  }, [clients, searchQuery]);

  const handleClientSelect = (client: Client) => {
    setFormData({ 
      ...formData, 
      clientId: client.id, 
      clientName: client.tradeName || client.legalName 
    });
    setSearchQuery(client.tradeName || client.legalName);
    setIsDropdownOpen(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
      <form 
        onSubmit={(e) => { e.preventDefault(); onSave(formData); }}
        className="w-full max-w-lg bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6 animate-in zoom-in-95"
      >
        <div className="flex items-center justify-between shrink-0">
           <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">
             {formData.id ? 'Update' : 'Add'} {category} Record
           </h3>
           <button type="button" onClick={onClose} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors">
              <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
           </button>
        </div>

        <div className="space-y-4">
          {/* Trade Name / GSTIN Search */}
          <div className="relative">
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Trade Name / GSTIN Search</label>
            <input 
              type="text"
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
              placeholder="Search by Trade Name or GSTIN..."
              value={searchQuery || (formData.clientId ? formData.clientName : '')}
              onChange={(e) => { setSearchQuery(e.target.value); setIsDropdownOpen(true); }}
              onFocus={() => setIsDropdownOpen(true)}
            />
            {isDropdownOpen && filteredClients.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-[120] max-h-48 overflow-y-auto no-scrollbar">
                {filteredClients.map(c => (
                  <button 
                    key={c.id} 
                    type="button"
                    onClick={() => handleClientSelect(c)}
                    className="w-full text-left px-4 py-3 hover:bg-indigo-50 border-b border-slate-50 last:border-0"
                  >
                    <p className="text-xs font-black text-slate-900 uppercase">{c.tradeName || c.legalName}</p>
                    <p className="text-[10px] text-indigo-600 font-mono tracking-tighter">{c.gstProfile?.gstin}</p>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Ref No (SCN/APL)</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.referenceNo || ''} onChange={e => setFormData({...formData, referenceNo: e.target.value.toUpperCase()})} placeholder="e.g. SCN/001/25" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Notice U/s</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.section || ''} onChange={e => setFormData({...formData, section: e.target.value.toUpperCase()})} placeholder="e.g. 61" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Tax Period</label>
            <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.taxPeriod || ''} onChange={e => setFormData({...formData, taxPeriod: e.target.value.toUpperCase()})} placeholder="e.g. APR-23 TO MAR-24" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Notice Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.issuedDate || ''} onChange={e => setFormData({...formData, issuedDate: e.target.value})} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Due Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.dueDate || ''} onChange={e => setFormData({...formData, dueDate: e.target.value})} />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Reply Status</label>
            <select 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.status}
              onChange={e => setFormData({...formData, status: e.target.value as LitigationStatus})}
            >
              <option value="Pending">Pending</option>
              <option value="Filed">Filed</option>
            </select>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Remark</label>
            <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20 focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.remarks || ''} onChange={e => setFormData({...formData, remarks: e.target.value})} placeholder="Add staff notes..." />
          </div>
        </div>

        <div className="flex gap-4 pt-4 shrink-0">
          <button type="button" onClick={onClose} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all active:scale-[0.98]">
            {formData.id ? 'Update Record' : 'Save Notice'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default NoticeForm;

import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';
import NoticeForm from '../Clientform/NoticeForm';

interface LitigationModuleProps {
  category: LitigationCategory;
  status: LitigationStatus;
}

const LitigationModule: React.FC<LitigationModuleProps> = ({ category, status }) => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  // Detail/View Modal
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<LitigationRecord | null>(null);

  // Inline Editing States
  const [editingRemarkId, setEditingRemarkId] = useState<string | null>(null);
  const [tempRemark, setTempRemark] = useState('');
  const [activeStatusMenuId, setActiveStatusMenuId] = useState<string | null>(null);

  // Column Specific Filters
  const [sectionFilter, setSectionFilter] = useState('All');
  const [daysLeftFilter, setDaysLeftFilter] = useState<'All' | 'Critical' | 'Healthy'>('All');
  const [replyStatusFilter, setReplyStatusFilter] = useState<'All' | 'Pending' | 'Overdue' | 'Filed'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'section' | 'days' | 'reply' | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      // Filter records for this specific page view
      setRecords(recs.filter(r => r.category === category && r.status === status));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (data: Partial<LitigationRecord>) => {
    if (!data.clientId || !data.referenceNo) {
      alert("Please select a client and enter a Reference Number.");
      return;
    }

    await mockBackend.saveLitigationRecord({
      ...data,
      category,
      status
    });
    setIsModalOpen(false);
    fetchAll();
  };

  const updateRecordStatus = async (id: string, newStatus: LitigationStatus) => {
    const all = await mockBackend.getLitigationRecords();
    const idx = all.findIndex(r => r.id === id);
    if (idx !== -1) {
      all[idx].status = newStatus;
      if (newStatus === 'Filed') {
        all[idx].filedDate = new Date().toISOString().split('T')[0];
      }
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(all));
      fetchAll();
    }
    setActiveStatusMenuId(null);
  };

  const saveRemark = async (id: string) => {
    const all = await mockBackend.getLitigationRecords();
    const idx = all.findIndex(r => r.id === id);
    if (idx !== -1) {
      all[idx].remarks = tempRemark;
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(all));
      fetchAll();
    }
    setEditingRemarkId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this litigation record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate).getTime();
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due - now.getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  const sectionCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    records.forEach(r => {
      const sec = r.section || 'N/A';
      counts[sec] = (counts[sec] || 0) + 1;
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [records]);

  const sections = useMemo(() => Array.from(new Set(records.map(r => r.section).filter(Boolean))).sort(), [records]);

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    let list = records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return (r.clientName || '').toLowerCase().includes(s) || 
             (r.referenceNo || '').toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });

    if (sectionFilter !== 'All') list = list.filter(r => r.section === sectionFilter);

    if (daysLeftFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        return daysLeftFilter === 'Critical' ? dl <= 7 : dl > 7;
      });
    }

    if (replyStatusFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        if (replyStatusFilter === 'Filed') return r.status === 'Filed';
        if (replyStatusFilter === 'Overdue') return r.status === 'Pending' && dl < 0;
        if (replyStatusFilter === 'Pending') return r.status === 'Pending' && dl >= 0;
        return true;
      });
    }

    return list;
  }, [records, clients, search, sectionFilter, daysLeftFilter, replyStatusFilter]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4 overflow-hidden">

      {/* Header Summary */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total {category}s</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>

          <div className="flex items-center gap-4 border-l border-slate-100 pl-6 overflow-x-auto no-scrollbar max-w-[500px]">
            {sectionCounts.map(([sec, count]) => (
              <div key={sec} className="text-center shrink-0">
                <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">U/s {sec}</p>
                <p className="text-sm font-black text-indigo-600 leading-none">{count}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search Trade Name, GSTIN or Ref No..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button 
          onClick={() => { setSelectedRecord(null); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add {category}
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1500px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S. No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px]">GSTIN</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px] relative">
                  <div className="flex items-center gap-1">
                    Notice U/s
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'section' ? null : 'section')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'section' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      <button onClick={() => { setSectionFilter('All'); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === 'All' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>All Sections</button>
                      {sections.map(s => (
                        <button key={s} onClick={() => { setSectionFilter(s); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === s ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>U/s {s}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[150px]">Tax Period</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Notice Date</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Due Date</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px] relative">
                  <div className="flex items-center gap-1">
                    Days Left
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'days' ? null : 'days')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'days' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Critical', 'Healthy'].map(opt => (
                        <button key={opt} onClick={() => { setDaysLeftFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${daysLeftFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px] relative">
                  <div className="flex items-center gap-1">
                    Reply Status
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'reply' ? null : 'reply')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'reply' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Pending', 'Overdue', 'Filed'].map(opt => (
                        <button key={opt} onClick={() => { setReplyStatusFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${replyStatusFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[220px]">Remark</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[120px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr><td colSpan={11} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No matching records</td></tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const dl = getDaysLeft(rec.dueDate);
                  const client = clients.find(c => c.id === rec.clientId);
                  const isOverdue = rec.status === 'Pending' && dl < 0;
                  const isCritical = rec.status === 'Pending' && dl <= 7 && dl >= 0;

                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                      <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5">
                        <p className="text-[11px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</p>
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-indigo-600 font-mono tracking-widest">
                        {client?.gstProfile?.gstin || 'N/A'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-600 uppercase">
                        {rec.section ? `U/s ${rec.section}` : '---'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-700 uppercase">
                        {rec.taxPeriod || '---'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{rec.issuedDate}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{rec.dueDate}</td>
                      <td className="px-4 py-5">
                         {rec.status === 'Filed' ? (
                           <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Completed</span>
                         ) : (
                           <div className="flex items-center gap-1.5">
                             <div className={`h-1.5 w-1.5 rounded-full ${isOverdue || isCritical ? 'bg-red-500 animate-pulse' : 'bg-amber-400'}`} />
                             <span className={`text-[11px] font-black ${isOverdue || isCritical ? 'text-red-500' : 'text-slate-700'}`}>
                               {dl < 0 ? `${Math.abs(dl)} days overdue` : `${dl} days left`}
                             </span>
                           </div>
                         )}
                      </td>
                      <td className="px-4 py-5 text-center relative">
                         <div className="relative inline-block text-left w-full">
                           <button 
                             onClick={() => setActiveStatusMenuId(activeStatusMenuId === rec.id ? null : rec.id)}
                             className={`w-full px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border flex items-center justify-between ${
                               rec.status === 'Filed' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' :
                               isOverdue ? 'bg-red-100 text-red-700 border-red-200' : 'bg-amber-100 text-amber-700 border-amber-200'
                             }`}
                           >
                             {rec.status === 'Filed' ? 'Filed' : isOverdue ? 'Overdue' : 'Pending'}
                             <svg className="h-3 w-3 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                           </button>
                           {activeStatusMenuId === rec.id && (
                             <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                                <button onClick={() => updateRecordStatus(rec.id, 'Pending')} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-slate-50 text-amber-600">Pending</button>
                                <button onClick={() => updateRecordStatus(rec.id, 'Filed')} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-slate-50 text-emerald-600">Filed</button>
                             </div>
                           )}
                         </div>
                      </td>
                      <td className="px-4 py-5">
                        {editingRemarkId === rec.id ? (
                           <div className="flex items-center gap-1">
                             <input 
                               autoFocus
                               className="w-full bg-white border border-indigo-200 rounded-lg p-2 text-[11px] font-bold outline-none ring-2 ring-indigo-50"
                               value={tempRemark}
                               onChange={e => setTempRemark(e.target.value)}
                               onBlur={() => saveRemark(rec.id)}
                               onKeyDown={e => e.key === 'Enter' && saveRemark(rec.id)}
                             />
                           </div>
                        ) : (
                          <div 
                            onClick={() => { setEditingRemarkId(rec.id); setTempRemark(rec.remarks || ''); }}
                            className="text-[11px] font-medium text-slate-500 truncate italic cursor-text hover:text-slate-900 hover:bg-indigo-50/50 rounded px-2 py-1 min-h-[1.5rem] transition-colors"
                          >
                            {rec.remarks || 'Click to add remark...'}
                          </div>
                        )}
                      </td>
                      <td className="px-4 py-5 text-right whitespace-nowrap">
                         <div className="flex items-center justify-end gap-2">
                            <button 
                              onClick={() => { setSelectedRecord(rec); setIsModalOpen(true); }}
                              className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm"
                              title="Edit Record"
                            >
                               <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                            </button>
                            <button 
                              onClick={() => { setViewingRecord(rec); setIsViewModalOpen(true); }}
                              className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm"
                              title="View Details"
                            >
                               <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                            </button>
                         </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* DETAILED VIEW MODAL */}
      {isViewModalOpen && viewingRecord && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col animate-in zoom-in-95">
              <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight truncate">{viewingRecord.clientName}</h3>
                    <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">{category} Details • Ref {viewingRecord.referenceNo}</p>
                 </div>
                 <button onClick={() => setIsViewModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200">
                   <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
                 </button>
              </div>
              <div className="p-10 grid grid-cols-2 gap-8">
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Notice U/s</p><p className="text-base font-black text-indigo-600">U/s {viewingRecord.section}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Tax Period</p><p className="text-base font-black text-slate-900 uppercase">{viewingRecord.taxPeriod || 'N/A'}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Notice Date</p><p className="text-base font-black text-slate-900">{viewingRecord.issuedDate}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Due Date</p><p className="text-base font-black text-red-500">{viewingRecord.dueDate}</p></div>
                 <div className="col-span-2 bg-slate-50 p-6 rounded-2xl border border-slate-100">
                    <p className="text-[10px] font-black uppercase text-slate-400 mb-2">Internal Staff Remarks</p>
                    <p className="text-sm font-medium text-slate-600 leading-relaxed italic">{viewingRecord.remarks || 'No internal notes found.'}</p>
                 </div>
              </div>
              <div className="p-8 border-t border-slate-100 flex justify-end gap-3">
                 <button onClick={() => { if(confirm('Delete record?')) handleDelete(viewingRecord.id); setIsViewModalOpen(false); }} className="px-6 py-3 text-red-500 font-black uppercase text-[10px] hover:bg-red-50 rounded-xl">Delete Record</button>
                 <button onClick={() => setIsViewModalOpen(false)} className="px-8 py-3 bg-indigo-600 text-white font-black uppercase text-[10px] rounded-xl shadow-lg">Close Details</button>
              </div>
           </div>
        </div>
      )}

      {/* Standalone Notice Form Modal */}
      <NoticeForm 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSave}
        clients={clients}
        category={category}
        initialData={selectedRecord}
      />
    </div>
  );
};

export default LitigationModule;

import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';
import NoticeForm from '../Clientform/NoticeForm';

interface LitigationModuleProps {
  category: LitigationCategory;
  status: LitigationStatus;
}

const LitigationModule: React.FC<LitigationModuleProps> = ({ category, status }) => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  // Detail/View Modal
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<LitigationRecord | null>(null);

  // Inline Editing States
  const [activeStatusMenuId, setActiveStatusMenuId] = useState<string | null>(null);

  // Column Specific Filters
  const [sectionFilter, setSectionFilter] = useState('All');
  const [daysLeftFilter, setDaysLeftFilter] = useState<'All' | 'Critical' | 'Healthy'>('All');
  const [replyStatusFilter, setReplyStatusFilter] = useState<'All' | 'Pending' | 'Overdue' | 'Filed'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'section' | 'days' | 'reply' | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      setRecords(recs.filter(r => r.category === category && r.status === status));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (data: Partial<LitigationRecord>) => {
    if (!data.clientId || !data.referenceNo) {
      alert("Please select a client and enter a Reference Number.");
      return;
    }

    await mockBackend.saveLitigationRecord({
      ...data,
      category,
      status
    });
    setIsModalOpen(false);
    setIsViewModalOpen(false); // Close view modal if we were editing from there
    fetchAll();
  };

  const updateRecordStatus = async (id: string, newStatus: LitigationStatus) => {
    const all = await mockBackend.getLitigationRecords();
    const idx = all.findIndex(r => r.id === id);
    if (idx !== -1) {
      all[idx].status = newStatus;
      if (newStatus === 'Filed') {
        all[idx].filedDate = new Date().toISOString().split('T')[0];
      }
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(all));
      fetchAll();
    }
    setActiveStatusMenuId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this litigation record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate).getTime();
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due - now.getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  const formatDisplayDate = (dateStr?: string) => {
    if (!dateStr) return '---';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const [y, m, d] = parts;
    return `${d}/${m}/${y}`;
  };

  const sectionCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    records.forEach(r => {
      const sec = r.section || 'N/A';
      counts[sec] = (counts[sec] || 0) + 1;
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [records]);

  const sections = useMemo(() => Array.from(new Set(records.map(r => r.section).filter(Boolean))).sort(), [records]);

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    let list = records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return (r.clientName || '').toLowerCase().includes(s) || 
             (r.referenceNo || '').toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });

    if (sectionFilter !== 'All') list = list.filter(r => r.section === sectionFilter);

    if (daysLeftFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        return daysLeftFilter === 'Critical' ? dl <= 7 : dl > 7;
      });
    }

    if (replyStatusFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        if (replyStatusFilter === 'Filed') return r.status === 'Filed';
        if (replyStatusFilter === 'Overdue') return r.status === 'Pending' && dl < 0;
        if (replyStatusFilter === 'Pending') return r.status === 'Pending' && dl >= 0;
        return true;
      });
    }

    return list;
  }, [records, clients, search, sectionFilter, daysLeftFilter, replyStatusFilter]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4 overflow-hidden">

      {/* Header Summary */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total {category}s</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>

          <div className="flex items-center gap-4 border-l border-slate-100 pl-6 overflow-x-auto no-scrollbar max-w-[500px]">
            {sectionCounts.map(([sec, count]) => (
              <div key={sec} className="text-center shrink-0">
                <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">U/s {sec}</p>
                <p className="text-sm font-black text-indigo-600 leading-none">{count}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search Trade Name, GSTIN or Ref No..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button 
          onClick={() => { setSelectedRecord(null); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add {category}
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S. No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[220px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px] relative">
                  <div className="flex items-center gap-1">
                    Notice U/s
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'section' ? null : 'section')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'section' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      <button onClick={() => { setSectionFilter('All'); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === 'All' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>All Sections</button>
                      {sections.map(s => (
                        <button key={s} onClick={() => { setSectionFilter(s); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === s ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>U/s {s}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[150px]">Tax Period</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Notice Date</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Due Date</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px] relative">
                  <div className="flex items-center gap-1">
                    Days Left
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'days' ? null : 'days')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'days' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Critical', 'Healthy'].map(opt => (
                        <button key={opt} onClick={() => { setDaysLeftFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${daysLeftFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px] relative">
                  <div className="flex items-center gap-1">
                    Reply Status
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'reply' ? null : 'reply')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                    </button>
                  </div>
                  {activeHeaderFilter === 'reply' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Pending', 'Overdue', 'Filed'].map(opt => (
                        <button key={opt} onClick={() => { setReplyStatusFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${replyStatusFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{opt}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr><td colSpan={10} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No matching records</td></tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const dl = getDaysLeft(rec.dueDate);
                  const client = clients.find(c => c.id === rec.clientId);
                  const isOverdue = rec.status === 'Pending' && dl < 0;
                  const isCritical = rec.status === 'Pending' && dl <= 7 && dl >= 0;

                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                      <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5">
                        <p className="text-[11px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</p>
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-indigo-600 font-mono tracking-widest">
                        {client?.gstProfile?.gstin || 'N/A'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-600 uppercase">
                        {rec.section ? `U/s ${rec.section}` : '---'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-700 uppercase">
                        {rec.taxPeriod || '---'}
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{formatDisplayDate(rec.issuedDate)}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{formatDisplayDate(rec.dueDate)}</td>
                      <td className="px-4 py-5">
                         {rec.status === 'Filed' ? (
                           <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Completed</span>
                         ) : (
                           <div className="flex items-center gap-1.5">
                             <div className={`h-1.5 w-1.5 rounded-full ${isOverdue || isCritical ? 'bg-red-500 animate-pulse' : 'bg-amber-400'}`} />
                             <span className={`text-[11px] font-black ${isOverdue || isCritical ? 'text-red-500' : 'text-slate-700'}`}>
                               {dl < 0 ? `${Math.abs(dl)} days overdue` : `${dl} days left`}
                             </span>
                           </div>
                         )}
                      </td>
                      <td className="px-4 py-5 text-center relative">
                         <div className="relative inline-block text-left w-full">
                           <button 
                             onClick={() => setActiveStatusMenuId(activeStatusMenuId === rec.id ? null : rec.id)}
                             className={`w-full px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border flex items-center justify-between ${
                               rec.status === 'Filed' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' :
                               isOverdue ? 'bg-red-100 text-red-700 border-red-200' : 'bg-amber-100 text-amber-700 border-amber-200'
                             }`}
                           >
                             {rec.status === 'Filed' ? 'Filed' : isOverdue ? 'Overdue' : 'Pending'}
                             <svg className="h-3 w-3 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                           </button>
                           {activeStatusMenuId === rec.id && (
                             <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                                <button onClick={() => updateRecordStatus(rec.id, 'Pending')} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-slate-50 text-amber-600">Pending</button>
                                <button onClick={() => updateRecordStatus(rec.id, 'Filed')} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-slate-50 text-emerald-600">Filed</button>
                             </div>
                           )}
                         </div>
                      </td>
                      <td className="px-4 py-5 text-right whitespace-nowrap">
                         <button 
                           onClick={() => { setViewingRecord(rec); setIsViewModalOpen(true); }}
                           className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm"
                           title="View Details"
                         >
                            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                         </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* DETAILED VIEW MODAL */}
      {isViewModalOpen && viewingRecord && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col animate-in zoom-in-95">
              <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight truncate">{viewingRecord.clientName}</h3>
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1">
                      Legal Name: {clients.find(c => c.id === viewingRecord.clientId)?.legalName || '---'}
                    </p>
                 </div>
                 <div className="flex items-center gap-2">
                    <button 
                      onClick={() => { setSelectedRecord(viewingRecord); setIsModalOpen(true); }}
                      className="bg-indigo-600 text-white font-black uppercase text-[10px] px-6 py-3 rounded-xl shadow-lg hover:bg-slate-900 transition-all"
                    >
                      Edit Record
                    </button>
                    <button onClick={() => setIsViewModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200">
                      <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
                    </button>
                 </div>
              </div>
              <div className="p-10 grid grid-cols-2 gap-8">
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">GSTIN Identifier</p><p className="text-base font-black text-indigo-600 font-mono">{clients.find(c => c.id === viewingRecord.clientId)?.gstProfile?.gstin || 'N/A'}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Notice U/s</p><p className="text-base font-black text-slate-900">U/s {viewingRecord.section}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Reference Number</p><p className="text-base font-black text-slate-900 uppercase">{viewingRecord.referenceNo}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Tax Period</p><p className="text-base font-black text-slate-900 uppercase">{viewingRecord.taxPeriod || 'N/A'}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Notice Date</p><p className="text-base font-black text-slate-900">{formatDisplayDate(viewingRecord.issuedDate)}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Due Date</p><p className="text-base font-black text-red-500">{formatDisplayDate(viewingRecord.dueDate)}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Current Status</p><p className="text-base font-black text-indigo-600 uppercase">{viewingRecord.status}</p></div>
                 {viewingRecord.filedDate && <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Date of Reply</p><p className="text-base font-black text-emerald-600">{formatDisplayDate(viewingRecord.filedDate)}</p></div>}
                 <div className="col-span-2 bg-slate-50 p-6 rounded-2xl border border-slate-100">
                    <p className="text-[10px] font-black uppercase text-slate-400 mb-2">Internal Staff Remarks</p>
                    <p className="text-sm font-medium text-slate-600 leading-relaxed italic">{viewingRecord.remarks || 'No internal notes found.'}</p>
                 </div>
              </div>
              <div className="p-8 border-t border-slate-100 flex justify-end gap-3">
                 <button onClick={() => { if(confirm('Delete record?')) handleDelete(viewingRecord.id); setIsViewModalOpen(false); }} className="px-6 py-3 text-red-500 font-black uppercase text-[10px] hover:bg-red-50 rounded-xl">Delete Record</button>
                 <button onClick={() => setIsViewModalOpen(false)} className="px-8 py-3 bg-slate-100 text-slate-600 font-black uppercase text-[10px] rounded-xl">Close Details</button>
              </div>
           </div>
        </div>
      )}

      {/* Standalone Notice Form Modal */}
      <NoticeForm 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSave}
        clients={clients}
        category={category}
        initialData={selectedRecord}
      />
    </div>
  );
};

export default LitigationModule;

import React, { useState, useMemo, useEffect } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';

interface NoticeFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: Partial<LitigationRecord>) => void;
  clients: Client[];
  category: LitigationCategory;
  initialData?: Partial<LitigationRecord> | null;
}

const NoticeForm: React.FC<NoticeFormProps> = ({ isOpen, onClose, onSave, clients, category, initialData }) => {
  const [formData, setFormData] = useState<Partial<LitigationRecord>>({
    status: 'Pending',
    category: category,
    taxPeriod: '',
    section: '',
    referenceNo: '',
    issuedDate: '',
    dueDate: '',
    remarks: ''
  });

  const [searchQuery, setSearchQuery] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
      setSearchQuery(initialData.clientName || '');
    } else {
      setFormData({
        status: 'Pending',
        category: category,
        taxPeriod: '',
        section: '',
        referenceNo: '',
        issuedDate: '',
        dueDate: '',
        remarks: ''
      });
      setSearchQuery('');
    }
  }, [initialData, isOpen, category]);

  const filteredClients = useMemo(() => {
    const s = searchQuery.toLowerCase();
    if (!s) return [];
    return clients.filter(c => 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(s) ||
      (c.legalName || '').toLowerCase().includes(s)
    );
  }, [clients, searchQuery]);

  const handleClientSelect = (client: Client) => {
    setFormData({ 
      ...formData, 
      clientId: client.id, 
      clientName: client.tradeName || client.legalName 
    });
    setSearchQuery(client.tradeName || client.legalName);
    setIsDropdownOpen(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[130] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
      <form 
        onSubmit={(e) => { e.preventDefault(); onSave(formData); }}
        className="w-full max-w-lg bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6 animate-in zoom-in-95"
      >
        <div className="flex items-center justify-between shrink-0">
           <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">
             {formData.id ? 'Update' : 'Add'} {category} Record
           </h3>
           <button type="button" onClick={onClose} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors">
              <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
           </button>
        </div>

        <div className="space-y-4">
          {/* Trade Name / GSTIN Search */}
          <div className="relative">
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Trade Name / GSTIN Search</label>
            <input 
              type="text"
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
              placeholder="Search by Trade Name or GSTIN..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setIsDropdownOpen(true); }}
              onFocus={() => setIsDropdownOpen(true)}
            />
            {isDropdownOpen && filteredClients.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-[140] max-h-48 overflow-y-auto no-scrollbar">
                {filteredClients.map(c => (
                  <button 
                    key={c.id} 
                    type="button"
                    onClick={() => handleClientSelect(c)}
                    className="w-full text-left px-4 py-3 hover:bg-indigo-50 border-b border-slate-50 last:border-0"
                  >
                    <p className="text-xs font-black text-slate-900 uppercase">{c.tradeName || c.legalName}</p>
                    <p className="text-[10px] text-indigo-600 font-mono tracking-tighter">{c.gstProfile?.gstin}</p>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Ref No (SCN/APL)</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.referenceNo || ''} onChange={e => setFormData({...formData, referenceNo: e.target.value.toUpperCase()})} placeholder="e.g. SCN/001/25" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Notice U/s</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.section || ''} onChange={e => setFormData({...formData, section: e.target.value.toUpperCase()})} placeholder="e.g. 61" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Tax Period</label>
            <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.taxPeriod || ''} onChange={e => setFormData({...formData, taxPeriod: e.target.value.toUpperCase()})} placeholder="e.g. APR-23 TO MAR-24" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Notice Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.issuedDate || ''} onChange={e => setFormData({...formData, issuedDate: e.target.value})} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Due Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.dueDate || ''} onChange={e => setFormData({...formData, dueDate: e.target.value})} />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Reply Status</label>
            <select 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.status}
              onChange={e => setFormData({...formData, status: e.target.value as LitigationStatus})}
            >
              <option value="Pending">Pending</option>
              <option value="Filed">Filed</option>
            </select>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Remark</label>
            <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20 focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.remarks || ''} onChange={e => setFormData({...formData, remarks: e.target.value})} placeholder="Add staff notes..." />
          </div>
        </div>

        <div className="flex gap-4 pt-4 shrink-0">
          <button type="button" onClick={onClose} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all active:scale-[0.98]">
            {formData.id ? 'Update Record' : 'Save Notice'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default NoticeForm;

import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, Client, LitigationStatus } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';
import NoticeForm from '../../Clientform/NoticeForm';

const NoticePending: React.FC = () => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  // Detail/View Modal
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<LitigationRecord | null>(null);

  // Inline Status Menu
  const [activeStatusMenuId, setActiveStatusMenuId] = useState<string | null>(null);

  // Column Specific Filters
  const [sectionFilter, setSectionFilter] = useState('All');
  const [daysLeftFilter, setDaysLeftFilter] = useState<'All' | 'Critical' | 'Healthy'>('All');
  const [replyStatusFilter, setReplyStatusFilter] = useState<'All' | 'Pending' | 'Overdue'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'section' | 'days' | 'reply' | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      // Filter strictly for Pending Notices
      setRecords(recs.filter(r => r.category === 'Notice' && r.status === 'Pending'));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, []);

  const handleSave = async (data: Partial<LitigationRecord>) => {
    if (!data.clientId || !data.referenceNo) {
      alert("Please select a client and enter a Reference Number.");
      return;
    }

    await mockBackend.saveLitigationRecord({
      ...data,
      category: 'Notice',
      // If we are editing and they changed status to Filed, it will move on next fetch
    });
    setIsModalOpen(false);
    setIsViewModalOpen(false);
    fetchAll();
  };

  const updateRecordStatus = async (id: string, newStatus: LitigationStatus) => {
    const all = await mockBackend.getLitigationRecords();
    const idx = all.findIndex(r => r.id === id);
    if (idx !== -1) {
      all[idx].status = newStatus;
      if (newStatus === 'Filed') {
        all[idx].filedDate = new Date().toISOString().split('T')[0];
      }
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(all));
      fetchAll();
    }
    setActiveStatusMenuId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this notice record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const formatDisplayDate = (dateStr?: string) => {
    if (!dateStr) return '---';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const [y, m, d] = parts;
    return `${d}/${m}/${y}`;
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate).getTime();
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due - now.getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  };

  const sectionCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    records.forEach(r => {
      const sec = r.section || 'N/A';
      counts[sec] = (counts[sec] || 0) + 1;
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [records]);

  const sections = useMemo(() => Array.from(new Set(records.map(r => r.section).filter(Boolean))).sort(), [records]);

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    let list = records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return (r.clientName || '').toLowerCase().includes(s) || 
             (r.referenceNo || '').toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });

    if (sectionFilter !== 'All') list = list.filter(r => r.section === sectionFilter);

    if (daysLeftFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        return daysLeftFilter === 'Critical' ? dl <= 7 : dl > 7;
      });
    }

    if (replyStatusFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        if (replyStatusFilter === 'Overdue') return dl < 0;
        if (replyStatusFilter === 'Pending') return dl >= 0;
        return true;
      });
    }

    return list;
  }, [records, clients, search, sectionFilter, daysLeftFilter, replyStatusFilter]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4 overflow-hidden">

      {/* Header Summary */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Pending Notices</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>

          <div className="flex items-center gap-4 border-l border-slate-100 pl-6 overflow-x-auto no-scrollbar max-w-[500px]">
            {sectionCounts.map(([sec, count]) => (
              <div key={sec} className="text-center shrink-0">
                <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">U/s {sec}</p>
                <p className="text-sm font-black text-indigo-600 leading-none">{count}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search Trade Name, GSTIN or Ref No..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button 
          onClick={() => { setSelectedRecord(null); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add Notice
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S. No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[220px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px] relative">
                  <div className="flex items-center gap-1">
                    Notice U/s
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'section' ? null : 'section')} className="p-1 hover:bg-white rounded transition-colors shadow-sm">
                      <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
