              <div className="p-8 border-t border-slate-100 flex justify-end gap-3 shrink-0"><button onClick={() => setIsViewModalOpen(false)} className="px-8 py-3 bg-slate-100 text-slate-600 font-black uppercase text-[10px] rounded-xl transition-colors">Close Details</button></div>
           </div>
        </div>
      )}

      <NoticeForm isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSave} clients={clients} category="HighCourt" initialData={selectedRecord} />
    </div>
  );
};

export default CourtPending;

import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, Client, LitigationStatus, LitigationCategory } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import Loader from '../../components/Loader';
import NoticeForm from '../Clientform/NoticeForm';

interface LitigationModuleProps {
  category: LitigationCategory;
  status: LitigationStatus;
}

/**
 * Generalized Litigation Module for handling Appeals, Tribunal, and High Court matters.
 * Features tracking, status management, and detailed record vaulting.
 */
const LitigationModule: React.FC<LitigationModuleProps> = ({ category, status }) => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<LitigationRecord | null>(null);

  const [activeStatusMenuId, setActiveStatusMenuId] = useState<string | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      // Filter by category and current active status
      setRecords(recs.filter(r => r.category === category && r.status === status));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (data: Partial<LitigationRecord>) => {
    await mockBackend.saveLitigationRecord({
      ...data,
      category: category,
    });
    setIsModalOpen(false);
    setIsViewModalOpen(false);
    fetchAll();
  };

  const updateRecordStatus = async (id: string, newStatus: LitigationStatus) => {
    const all = await mockBackend.getLitigationRecords();
    const idx = all.findIndex(r => r.id === id);
    if (idx !== -1) {
      all[idx].status = newStatus;
      if (newStatus === 'Filed') {
        all[idx].filedDate = new Date().toISOString().split('T')[0];
      }
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(all));
      fetchAll();
    }
    setActiveStatusMenuId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this litigation record?')) {
      const all = await mockBackend.getLitigationRecords();
      const filtered = all.filter(r => r.id !== id);
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(filtered));
      fetchAll();
    }
  };

  const formatDisplayDate = (dateStr?: string) => {
    if (!dateStr) return '---';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const [y, m, d] = parts;
    return `${d}/${m}/${y}`;
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due.getTime() - now.getTime();
    return Math.round(diff / (1000 * 60 * 60 * 24));
  };

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    return records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return (r.clientName || '').toLowerCase().includes(s) || 
             (r.referenceNo || '').toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });
  }, [records, clients, search]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in duration-500 h-full flex flex-col space-y-4 overflow-hidden">

      {/* Search and Action Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{status} {category}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder={`Search ${category} records...`} 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {status === 'Pending' && (
          <button 
            onClick={() => { setSelectedRecord(null); setIsModalOpen(true); }}
            className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            Add {category}
          </button>
        )}
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1100px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S. No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[220px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Notice U/s</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[150px]">Reference No</th>

                {status === 'Pending' && <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Due Date</th>}
                {status === 'Filed' && <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Filing Date</th>}
                {(status === 'Drop' || status === 'Demand') && <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Order Date</th>}

                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-center w-[160px]">Status</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr><td colSpan={9} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No {status.toLowerCase()} records found</td></tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const client = clients.find(c => c.id === rec.clientId);
                  const dl = rec.dueDate ? getDaysLeft(rec.dueDate) : 0;
                  const isOverdue = status === 'Pending' && dl < 0;

                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                      <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5">
                        <p className="text-[11px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</p>
                      </td>
                      <td className="px-4 py-5 text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client?.gstProfile?.gstin || 'N/A'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-600 uppercase">{rec.section || '---'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-700 uppercase truncate">{rec.referenceNo}</td>

                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">
                        {status === 'Pending' ? formatDisplayDate(rec.dueDate) : 
                         status === 'Filed' ? formatDisplayDate(rec.filedDate) : 
                         formatDisplayDate(rec.issuedDate)}
                      </td>

                      <td className="px-4 py-5 text-center relative">
                         <div className="relative inline-block text-left w-full">
                           <button 
                             onClick={() => setActiveStatusMenuId(activeStatusMenuId === rec.id ? null : rec.id)}
                             className={`w-full px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border flex items-center justify-between ${
                               status === 'Filed' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' :
                               status === 'Drop' ? 'bg-blue-100 text-blue-700 border-blue-200' :
                               status === 'Demand' ? 'bg-red-100 text-red-700 border-red-200' :
                               isOverdue ? 'bg-red-100 text-red-700 border-red-200' : 'bg-amber-100 text-amber-700 border-amber-200'
                             }`}
                           >
                             {status === 'Pending' && isOverdue ? 'Overdue' : status}
                             <svg className="h-3 w-3 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                           </button>
                           {activeStatusMenuId === rec.id && (
                             <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                                {['Pending', 'Filed', 'Drop', 'Demand'].map(s => (
                                  <button key={s} onClick={() => updateRecordStatus(rec.id, s as LitigationStatus)} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-slate-50">{s}</button>
                                ))}
                             </div>
                           )}
                         </div>
                      </td>

                      <td className="px-4 py-5 text-right whitespace-nowrap">
                         <button onClick={() => { setViewingRecord(rec); setIsViewModalOpen(true); }} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm">
                            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                         </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* DETAIL VIEW MODAL */}
      {isViewModalOpen && viewingRecord && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col animate-in zoom-in-95">
              <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
                 <div className="min-w-0">
                    <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight truncate">{viewingRecord.clientName}</h3>
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1">Category: {category} • Current Status: {status}</p>
                 </div>
                 <div className="flex items-center gap-2">
                    <button onClick={() => { setSelectedRecord(viewingRecord); setIsModalOpen(true); }} className="bg-indigo-600 text-white font-black uppercase text-[10px] px-6 py-3 rounded-xl shadow-lg hover:bg-slate-900 transition-all">Edit Record</button>
                    <button onClick={() => setIsViewModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
                 </div>
              </div>
              <div className="p-10 grid grid-cols-2 gap-8">
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Section</p><p className="text-base font-black text-slate-900">U/s {viewingRecord.section || '---'}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Reference No.</p><p className="text-base font-black text-slate-900 uppercase">{viewingRecord.referenceNo}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Date of Issue</p><p className="text-base font-black text-slate-900">{formatDisplayDate(viewingRecord.issuedDate)}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Response Due Date</p><p className="text-base font-black text-red-500">{formatDisplayDate(viewingRecord.dueDate)}</p></div>
                 {viewingRecord.filedDate && <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Filing Record Date</p><p className="text-base font-black text-emerald-600">{formatDisplayDate(viewingRecord.filedDate)}</p></div>}
                 <div className="col-span-2 bg-slate-50 p-6 rounded-2xl border border-slate-100"><p className="text-[10px] font-black uppercase text-slate-400 mb-2">Internal Staff Remarks</p><p className="text-sm font-medium text-slate-600 italic leading-relaxed">{viewingRecord.remarks || 'No notes found in vault.'}</p></div>
              </div>
              <div className="p-8 border-t border-slate-100 flex justify-end gap-3 shrink-0">
                 <button onClick={() => { handleDelete(viewingRecord.id); setIsViewModalOpen(false); }} className="px-6 py-3 text-red-500 font-black uppercase text-[10px] hover:bg-red-50 rounded-xl transition-colors">Delete Entry</button>
                 <button onClick={() => setIsViewModalOpen(false)} className="px-8 py-3 bg-slate-100 text-slate-600 font-black uppercase text-[10px] rounded-xl transition-colors">Close View</button>
              </div>
           </div>
        </div>
      )}

      <NoticeForm 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSave}
        clients={clients}
        category={category}
        initialData={selectedRecord}
      />
    </div>
  );
};

