            <input 
              type="text"
              readOnly={!!initialData}
              className={`w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all ${initialData ? 'opacity-70' : ''}`}
              placeholder="Search by Trade Name or GSTIN..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setIsDropdownOpen(true); }}
              onFocus={() => !initialData && setIsDropdownOpen(true)}
            />
            {isDropdownOpen && !initialData && filteredClients.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-[140] max-h-48 overflow-y-auto no-scrollbar">
                {filteredClients.map(c => (
                  <button 
                    key={c.id} 
                    type="button"
                    onClick={() => handleClientSelect(c)}
                    className="w-full text-left px-4 py-3 hover:bg-indigo-50 border-b border-slate-50 last:border-0"
                  >
                    <p className="text-xs font-black text-slate-900 uppercase">{c.tradeName || c.legalName}</p>
                    <p className="text-[10px] text-indigo-600 font-mono tracking-tighter">{c.gstProfile?.gstin}</p>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">{isNotice ? 'Notice Ref No' : 'Order Ref No'}</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                required
                value={formData.referenceNo || ''} onChange={e => setFormData({...formData, referenceNo: e.target.value.toUpperCase()})} placeholder="Reference No..." />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">{isNotice ? 'Notice U/s' : 'Order Section'}</label>
              <input className="w-full bg-slate-50 border-none rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-2 focus:ring-indigo-600/10 transition-all"
                required
                value={formData.section || ''} onChange={e => setFormData({...formData, section: e.target.value.toUpperCase()})} placeholder="Section No..." />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Tax Period</label>
            <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.taxPeriod || ''} onChange={e => setFormData({...formData, taxPeriod: e.target.value.toUpperCase()})} placeholder="e.g. APR-23 TO MAR-24" />
          </div>

          <div className={`grid gap-4 ${isReissue ? 'grid-cols-1' : 'grid-cols-2'}`}>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">{isNotice ? 'Notice Date' : 'Order Date (from AO)'}</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                required
                value={formData.issuedDate || ''} onChange={e => handleDateChange(e.target.value)} />
            </div>
            {!isReissue && (
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Response Due Date</label>
                <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                  required={formData.status === 'Pending'}
                  value={formData.dueDate || ''} onChange={e => setFormData({...formData, dueDate: e.target.value})} />
              </div>
            )}
          </div>

          {isReissue && (
             <div className="bg-amber-50 p-4 rounded-xl border border-amber-100">
                <p className="text-[9px] font-black text-amber-500 uppercase tracking-widest mb-1">Calculated Due Date (90 Days)</p>
                <p className="text-sm font-black text-amber-900">{formData.dueDate ? new Date(formData.dueDate).toLocaleDateString('en-GB') : '---'}</p>
             </div>
          )}

          {!isReissue && (
            <div className={`grid gap-4 ${formData.status === 'Filed' || formData.status === 'Drop' || formData.status === 'Demand' ? 'grid-cols-2' : 'grid-cols-1'}`}>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Status</label>
                <select 
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                  value={formData.status}
                  onChange={e => handleStatusChange(e.target.value as LitigationStatus)}
                >
                  <option value="Pending">Pending</option>
                  <option value="Filed">Filed</option>
                  <option value="Drop">{isNotice ? 'Drop Order' : 'Relief Granted'}</option>
                  <option value="Demand">{isNotice ? 'Demand Order' : 'Sustained (Demand)'}</option>
                </select>
              </div>
              {formData.status === 'Filed' && (
                <div className="animate-in slide-in-from-left-2 duration-300">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Reply Filed Date</label>
                  <input type="date" className="w-full bg-white border border-indigo-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all shadow-sm"
                    required
                    value={formData.filedDate || ''} onChange={e => setFormData({...formData, filedDate: e.target.value})} />
                </div>
              )}
              {(formData.status === 'Drop' || formData.status === 'Demand') && (
                <div className="animate-in slide-in-from-left-2 duration-300">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Order Date</label>
                  <input type="date" className="w-full bg-white border border-indigo-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all shadow-sm"
                    required
                    value={formData.orderDate || ''} onChange={e => setFormData({...formData, orderDate: e.target.value})} />
                </div>
              )}
            </div>
          )}

          {formData.status === 'Filed' && !isNotice && (
            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Next Hearing Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.hearingDate || ''} onChange={e => setFormData({...formData, hearingDate: e.target.value})} />
            </div>
          )}

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Remark</label>
            <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20 focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.remarks || ''} onChange={e => setFormData({...formData, remarks: e.target.value})} placeholder="Add staff notes..." />
          </div>
        </div>

        <div className="flex gap-4 pt-4 shrink-0">
          <button type="button" onClick={onClose} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all active:scale-[0.98]">
            {isReissue ? `Issue ${category}` : (formData.id ? 'Update Record' : 'Save Record')}
          </button>
        </div>
      </form>
    </div>
  );
};

export default NoticeForm;

import React, { useState, useEffect, useMemo } from 'react';
import { LitigationRecord, Client, LitigationStatus, LitigationCategory } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';
import NoticeForm from '../../Clientform/NoticeForm';

const AppealFiled: React.FC = () => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<LitigationRecord | null>(null);

  const [activeStatusMenuId, setActiveStatusMenuId] = useState<string | null>(null);
  const [targetCategory, setTargetCategory] = useState<LitigationCategory>('Appeal');
  const [isReissueMode, setIsReissueMode] = useState(false);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([
        mockBackend.getLitigationRecords(),
        mockBackend.getClients()
      ]);
      setRecords(recs.filter(r => r.category === 'Appeal' && r.status === 'Filed'));
      setClients(clis);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchAll(); }, []);

  const handleSave = async (data: Partial<LitigationRecord>) => {
    await mockBackend.saveLitigationRecord({ ...data });
    setIsModalOpen(false);
    setIsViewModalOpen(false);
    setIsReissueMode(false);
    fetchAll();
  };

  const updateRecordStatus = async (id: string, newStatus: LitigationStatus) => {
    const all = await mockBackend.getLitigationRecords();
    const idx = all.findIndex(r => r.id === id);
    if (idx !== -1) {
      all[idx].status = newStatus;
      if (newStatus === 'Drop' || newStatus === 'Demand') {
        all[idx].orderDate = new Date().toISOString().split('T')[0];
      }
      localStorage.setItem('clientify_mock_litigation', JSON.stringify(all));
      fetchAll();
    }
    setActiveStatusMenuId(null);
  };

  const formatDisplayDate = (dateStr?: string) => {
    if (!dateStr) return '---';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const [y, m, d] = parts;
    return `${d}/${m}/${y}`;
  };

  const getHearingDaysLeft = (hearingDate?: string) => {
    if (!hearingDate) return null;
    const due = new Date(hearingDate);
    due.setHours(0, 0, 0, 0);
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due.getTime() - now.getTime();
    return Math.round(diff / (1000 * 60 * 60 * 24));
  };

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    return records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return (r.clientName || '').toLowerCase().includes(s) || 
             (r.referenceNo || '').toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });
  }, [records, clients, search]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in duration-500 h-full flex flex-col space-y-4 overflow-hidden">
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Filed Appeals</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>
        </div>
        <div className="relative flex-1 group w-full">
          <input type="text" placeholder="Search filed appeals..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1500px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No.</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Trade Name</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[130px]">Order U/s</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[150px]">Order Ref No</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Filing Date</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[140px]">Hearing Date</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[120px]">Days Left</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 w-[160px] text-center">Status</th>
                <th className="px-4 py-5 text-[11px] font-black uppercase tracking-widest text-slate-400 text-right w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr><td colSpan={10} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No filed appeals found</td></tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const client = clients.find(c => c.id === rec.clientId);
                  const hDays = getHearingDaysLeft(rec.hearingDate);
                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group">
                      <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client?.gstProfile?.gstin || 'N/A'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-600 uppercase">{rec.section || '---'}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-700 uppercase truncate">{rec.referenceNo}</td>
                      <td className="px-4 py-5 text-[11px] font-black text-slate-500 uppercase">{formatDisplayDate(rec.filedDate)}</td>
                      <td className="px-4 py-5">
                         <div className="flex items-center gap-1.5 text-[11px] font-black text-slate-700 uppercase">
                            <svg className="h-3.5 w-3.5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                            {formatDisplayDate(rec.hearingDate)}
                         </div>
                      </td>
                      <td className="px-4 py-5">
                         {hDays !== null ? (
                           <span className={`text-[11px] font-black uppercase ${hDays < 0 ? 'text-red-500' : hDays <= 7 ? 'text-orange-500' : 'text-emerald-600'}`}>
                              {hDays < 0 ? `${Math.abs(hDays)} Overdue` : `${hDays} Days`}
                           </span>
                         ) : <span className="text-slate-300">---</span>}
                      </td>
                      <td className="px-4 py-5 text-center relative">
                        <div className="relative inline-block w-full">
                           <button 
                             onClick={() => setActiveStatusMenuId(activeStatusMenuId === rec.id ? null : rec.id)}
                             className="w-full px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest bg-emerald-50 text-emerald-600 border border-emerald-100 hover:bg-emerald-100 transition-all flex items-center justify-between"
                           >
                             Filed <svg className="h-3 w-3 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                           </button>
                           {activeStatusMenuId === rec.id && (
                             <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95 text-left">
                                <button onClick={() => updateRecordStatus(rec.id, 'Drop')} className="w-full px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-emerald-50 text-emerald-600 text-left">Relief Granted</button>
                                <button onClick={() => updateRecordStatus(rec.id, 'Demand')} className="w-full px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-red-50 text-red-600 text-left border-t border-slate-50">Sustained</button>
                             </div>
                           )}
                        </div>
                      </td>
                      <td className="px-4 py-5 text-right whitespace-nowrap">
                         <button onClick={() => { setViewingRecord(rec); setIsViewModalOpen(true); }} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm">
                            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                         </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isViewModalOpen && viewingRecord && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col animate-in zoom-in-95">
              <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
                 <div className="min-w-0">
                    <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight truncate">{viewingRecord.clientName}</h3>
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1">Legal ID: {clients.find(c => c.id === viewingRecord.clientId)?.legalName || '---'}</p>
                 </div>
                 <div className="flex items-center gap-2">
                    <button onClick={() => { setSelectedRecord(viewingRecord); setTargetCategory('Appeal'); setIsModalOpen(true); }} className="bg-indigo-600 text-white font-black uppercase text-[10px] px-6 py-3 rounded-xl shadow-lg">Edit</button>
                    <button onClick={() => setIsViewModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
                 </div>
              </div>
              <div className="p-10 grid grid-cols-2 gap-8">
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Order Section</p><p className="text-base font-black text-slate-900">U/s {viewingRecord.section}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Order Ref No</p><p className="text-base font-black text-slate-900 uppercase">{viewingRecord.referenceNo}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Tax Period</p><p className="text-base font-black text-slate-900 uppercase">{viewingRecord.taxPeriod || 'N/A'}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Date of Filing</p><p className="text-base font-black text-emerald-600">{formatDisplayDate(viewingRecord.filedDate)}</p></div>
                 <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Hearing Date</p><p className="text-base font-black text-indigo-600">{formatDisplayDate(viewingRecord.hearingDate)}</p></div>
                 <div className="col-span-2 bg-slate-50 p-6 rounded-2xl border border-slate-100"><p className="text-[10px] font-black uppercase text-slate-400 mb-2">Internal Staff Remarks</p><p className="text-sm font-medium text-slate-600 italic leading-relaxed">{viewingRecord.remarks || 'No notes found.'}</p></div>
              </div>
              <div className="p-8 border-t border-slate-100 flex justify-end gap-3 shrink-0"><button onClick={() => setIsViewModalOpen(false)} className="px-8 py-3 bg-slate-100 text-slate-600 font-black uppercase text-[10px] rounded-xl transition-colors">Close</button></div>
           </div>
        </div>
      )}

      <NoticeForm 
        isOpen={isModalOpen} 
        onClose={() => { setIsModalOpen(false); setIsReissueMode(false); }} 
        onSave={handleSave} 
        clients={clients} 
        category={targetCategory} 
        initialData={selectedRecord}
        isReissue={isReissueMode}
      />
    </div>
  );
};

