import React, { useState, useMemo, useEffect } from 'react';
import { LitigationRecord, LitigationCategory, LitigationStatus, Client } from '../../types';

interface NoticeFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: Partial<LitigationRecord>) => void;
  clients: Client[];
  category: LitigationCategory;
  initialData?: Partial<LitigationRecord> | null;
  isReissue?: boolean;
}

const NoticeForm: React.FC<NoticeFormProps> = ({ isOpen, onClose, onSave, clients, category, initialData, isReissue }) => {
  const [formData, setFormData] = useState<Partial<LitigationRecord>>({
    status: 'Pending',
    category: category,
    taxPeriod: '',
    section: '',
    referenceNo: '',
    issuedDate: '',
    dueDate: '',
    filedDate: '',
    hearingDate: '',
    orderDate: '',
    remarks: '',
    previousNoticeRef: '',
    previousNoticeSection: '',
    isReissued: false
  });

  const [searchQuery, setSearchQuery] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  const isNotice = category === 'Notice';

  // Exactly 90 days helper
  const calculateDueDate = (dateStr: string) => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    date.setHours(0,0,0,0);
    date.setDate(date.getDate() + 90);
    return date.toISOString().split('T')[0];
  };

  useEffect(() => {
    if (initialData) {
      if (isReissue) {
        const sourceDate = initialData.orderDate || initialData.issuedDate || '';
        setFormData({
          ...initialData,
          previousNoticeRef: initialData.referenceNo,
          previousNoticeSection: initialData.section,
          referenceNo: initialData.referenceNo || '', 
          section: initialData.section || '',         
          status: 'Pending',
          isReissued: true,
          filedDate: '', // Do NOT pre-fill filing date for a new re-issue
          hearingDate: '',
          orderDate: sourceDate,
          issuedDate: sourceDate,
          dueDate: sourceDate ? calculateDueDate(sourceDate) : '',
          category: category 
        });
      } else {
        setFormData({
          ...initialData,
          filedDate: initialData.filedDate || '', // ONLY pre-fill if it exists
          orderDate: initialData.orderDate || ''
        });
      }
      setSearchQuery(initialData.clientName || '');
    } else {
      setFormData({
        status: 'Pending',
        category: category,
        taxPeriod: '',
        section: '',
        referenceNo: '',
        issuedDate: '',
        dueDate: '',
        filedDate: '',
        hearingDate: '',
        orderDate: '',
        remarks: '',
        isReissued: false
      });
      setSearchQuery('');
    }
  }, [initialData, isOpen, category, isReissue]);

  const filteredClients = useMemo(() => {
    const s = searchQuery.toLowerCase();
    if (!s) return [];
    return clients.filter(c => 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(s) ||
      (c.legalName || '').toLowerCase().includes(s)
    );
  }, [clients, searchQuery]);

  const handleClientSelect = (client: Client) => {
    setFormData({ 
      ...formData, 
      clientId: client.id, 
      clientName: client.tradeName || client.legalName 
    });
    setSearchQuery(client.tradeName || client.legalName);
    setIsDropdownOpen(false);
  };

  const handleStatusChange = (newStatus: LitigationStatus) => {
    setFormData(prev => ({
      ...prev,
      status: newStatus,
      // Only set dates automatically if the user moves TO that status and it's blank
      filedDate: (newStatus === 'Filed' && !prev.filedDate) ? new Date().toISOString().split('T')[0] : prev.filedDate,
      orderDate: ((newStatus === 'Drop' || newStatus === 'Demand') && !prev.orderDate) ? new Date().toISOString().split('T')[0] : prev.orderDate
    }));
  };

  const handleDateChange = (date: string) => {
    setFormData(prev => ({
      ...prev,
      issuedDate: date,
      orderDate: date,
      dueDate: (isReissue || !isNotice) ? calculateDueDate(date) : prev.dueDate
    }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[130] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
      <form 
        onSubmit={(e) => { e.preventDefault(); onSave(formData); }}
        className="w-full max-w-lg bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6 animate-in zoom-in-95"
      >
        <div className="flex items-center justify-between shrink-0">
           <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">
             {isReissue ? `Initiate ${category}` : (formData.id ? 'Update' : 'Add')} {category} Record
           </h3>
           <button type="button" onClick={onClose} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors">
              <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
           </button>
        </div>

        <div className="space-y-4">
          {!initialData && (
            <div className="relative">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Client Lookup</label>
              <input 
                type="text"
                className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                placeholder="Search by Trade Name or GSTIN..."
                value={searchQuery}
                onChange={(e) => { setSearchQuery(e.target.value); setIsDropdownOpen(true); }}
                onFocus={() => setIsDropdownOpen(true)}
              />
              {isDropdownOpen && filteredClients.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-[140] max-h-48 overflow-y-auto no-scrollbar">
                  {filteredClients.map(c => (
                    <button key={c.id} type="button" onClick={() => handleClientSelect(c)} className="w-full text-left px-4 py-3 hover:bg-indigo-50 border-b border-slate-50 last:border-0">
                      <p className="text-xs font-black text-slate-900 uppercase">{c.tradeName || c.legalName}</p>
                      <p className="text-[10px] text-indigo-600 font-mono tracking-tighter">{c.gstProfile?.gstin}</p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">{isNotice ? 'Notice Ref No' : 'Order Ref No'}</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                required
                value={formData.referenceNo || ''} onChange={e => setFormData({...formData, referenceNo: e.target.value.toUpperCase()})} placeholder="Reference No..." />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">{isNotice ? 'Notice U/s' : 'Order Section'}</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
                required
                value={formData.section || ''} onChange={e => setFormData({...formData, section: e.target.value.toUpperCase()})} placeholder="Section No..." />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Tax Period</label>
            <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none uppercase focus:ring-4 focus:ring-indigo-100 transition-all"
              value={formData.taxPeriod || ''} onChange={e => setFormData({...formData, taxPeriod: e.target.value.toUpperCase()})} placeholder="e.g. APR-23 TO MAR-24" />
          </div>

          <div className={`grid gap-4 ${isReissue ? 'grid-cols-1' : 'grid-cols-2'}`}>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">{isNotice ? 'Notice Date' : 'Order Date (Trigger)'}</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                required
                value={formData.issuedDate || ''} onChange={e => handleDateChange(e.target.value)} />
            </div>
            {!isReissue && (
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Response Due Date</label>
                <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                  required={formData.status === 'Pending'}
                  value={formData.dueDate || ''} onChange={e => setFormData({...formData, dueDate: e.target.value})} />
              </div>
            )}
          </div>

          {(isReissue || !isNotice) && formData.dueDate && (
             <div className="bg-amber-50 p-4 rounded-xl border border-amber-100 animate-in fade-in slide-in-from-top-2">
                <p className="text-[9px] font-black text-amber-500 uppercase tracking-widest mb-1">Timeline Due (Exactly 90 Days)</p>
                <p className="text-sm font-black text-amber-900">{new Date(formData.dueDate).toLocaleDateString('en-GB')}</p>
             </div>
          )}

          {!isReissue && (
            <div className={`grid gap-4 ${formData.status === 'Filed' || formData.status === 'Drop' || formData.status === 'Demand' ? 'grid-cols-2' : 'grid-cols-1'}`}>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Status</label>
                <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100"
                  value={formData.status} onChange={e => handleStatusChange(e.target.value as LitigationStatus)}>
                  <option value="Pending">Pending</option>
                  <option value="Filed">Filed</option>
                  <option value="Drop">{isNotice ? 'Drop Order' : 'Relief Granted'}</option>
                  <option value="Demand">{isNotice ? 'Demand Order' : 'Sustained (Demand)'}</option>
                </select>
              </div>
              {formData.status === 'Filed' && (
                <div className="animate-in slide-in-from-left-2 duration-300">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Reply Filed Date</label>
                  <input type="date" className="w-full bg-white border border-indigo-200 rounded-xl p-3.5 font-bold outline-none shadow-sm"
                    required
                    value={formData.filedDate || ''} onChange={e => setFormData({...formData, filedDate: e.target.value})} />
                </div>
              )}
              {(formData.status === 'Drop' || formData.status === 'Demand') && (
                <div className="animate-in slide-in-from-left-2 duration-300">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Order Date</label>
                  <input type="date" className="w-full bg-white border border-indigo-200 rounded-xl p-3.5 font-bold outline-none shadow-sm"
                    required
                    value={formData.orderDate || ''} onChange={e => setFormData({...formData, orderDate: e.target.value})} />
                </div>
              )}
            </div>
          )}

          {formData.status === 'Filed' && !isNotice && (
            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Next Hearing Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                value={formData.hearingDate || ''} onChange={e => setFormData({...formData, hearingDate: e.target.value})} />
            </div>
          )}

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Staff Remark</label>
            <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3.5 font-bold outline-none h-20"
              value={formData.remarks || ''} onChange={e => setFormData({...formData, remarks: e.target.value})} placeholder="Notes..." />
          </div>
        </div>

        <div className="flex gap-4 pt-4 shrink-0">
          <button type="button" onClick={onClose} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all active:scale-[0.98]">
            {isReissue ? `Issue ${category}` : (formData.id ? 'Update Record' : 'Save Record')}
          </button>
        </div>
      </form>
    </div>
  );
};

export default NoticeForm;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import Loader from '../../components/Loader';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
  onDataChange?: () => void;
}

const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All',
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());

  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const [tempPassword, setTempPassword] = useState('');
  const [showPassInView, setShowPassInView] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [localPassValue, setLocalPassValue] = useState('');
  const [showPassInLogin, setShowPassInLogin] = useState(false);
  const [isSavingPass, setIsSavingPass] = useState(false);

  const [gstStatusColFilter, setGstStatusColFilter] = useState<string>('All');
  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');
  const [openFilterCol, setOpenFilterCol] = useState<'gst' | 'status' | null>(null);

  const toggleRow = (id: string) => {
    setExpandedRows(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile) || []);
    } catch (error) {
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchClients(); }, []);

  const formatDate = (dateStr?: string) => {
    if (!dateStr || !dateStr.includes('-')) return dateStr || 'N/A';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];
    if (jurisdictionFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
      if (jurisdictionFilter === 'State' && sectorFilter !== 'All') list = list.filter(c => c.gstProfile?.sector === sectorFilter);
      if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') list = list.filter(c => c.gstProfile?.range === rangeFilter);
    }
    if (gstStatusColFilter !== 'All') list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
    if (clientStatusColFilter !== 'All') list = list.filter(c => c.status === clientStatusColFilter);

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleDataChange = () => {
    fetchClients();
    if (onDataChange) onDataChange();
  };

  const copyToClipboard = (text: string) => { navigator.clipboard.writeText(text); };
  const shareViaWhatsApp = (text: string) => { window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank'); };

  const handleUpdateGatewayPassword = async () => {
    if (!selectedClient) return;
    setIsSavingPass(true);
    try {
      const updatedClient = { ...selectedClient, gstProfile: { ...selectedClient.gstProfile!, password: tempPassword } };
      await mockBackend.saveClient(updatedClient);
      setSelectedClient(updatedClient);
      handleDataChange();
      setTimeout(() => setIsSavingPass(false), 800);
    } catch (err) { setIsSavingPass(false); }
  };

  const openPortalLogin = async (client: Client, finalPass?: string) => {
    if (finalPass && finalPass !== client.gstProfile?.password) {
      const updatedClient = { ...client, gstProfile: { ...client.gstProfile!, password: finalPass } };
      await mockBackend.saveClient(updatedClient);
      handleDataChange();
    }
    copyToClipboard(client.gstProfile?.username || '');
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  const getCredText = (client: Client) => `*GST Credentials for ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n_Shared via Clientify_`;

  if (isLoading) return <Loader />;

  // DEFINING GRID TEMPLATE
  // S.No (4rem) | Trade Name (Sticky - min-200) | GSTIN (180px) | Statuses (140px each) | Actions (120px)
  const gridTemplate = "grid-cols-[4rem_minmax(12.5rem,1fr)_11.25rem_8.75rem_8.75rem_7.5rem]";

  return (
    <div className="flex flex-col h-full overflow-hidden animate-in fade-in duration-500">
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">

        {/* SIZE-ADAPTIVE HEADER */}
        <div className={`hidden lg:grid ${gridTemplate} bg-slate-50 border-b border-slate-100 z-20 sticky top-0`}>
          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400">S.No.</div>
          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400 sticky left-0 bg-slate-50 z-10 border-r border-slate-100 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">Trade Name</div>
          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400">GSTIN</div>

          <div className="p-4 flex items-center justify-center gap-1.5 relative">
            <span className="text-[13px] font-black uppercase tracking-widest text-slate-400">GST Status</span>
            <button onClick={() => setOpenFilterCol(openFilterCol === 'gst' ? null : 'gst')} className="h-5 w-5 rounded bg-white border border-slate-200 text-slate-400 flex items-center justify-center shadow-sm">
              <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
            </button>
            {openFilterCol === 'gst' && (
              <div className="absolute top-full mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1.5 animate-in zoom-in-95">
                {['All', 'Active', 'Suspended', 'Cancelled'].map(opt => (
                  <button key={opt} onClick={() => { setGstStatusColFilter(opt); setOpenFilterCol(null); }} className={`w-full text-left px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-lg ${gstStatusColFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{opt}</button>
                ))}
              </div>
            )}
          </div>

          <div className="p-4 flex items-center justify-center gap-1.5 relative">
            <span className="text-[13px] font-black uppercase tracking-widest text-slate-400">Status</span>
            <button onClick={() => setOpenFilterCol(openFilterCol === 'status' ? null : 'status')} className="h-5 w-5 rounded bg-white border border-slate-200 text-slate-400 flex items-center justify-center shadow-sm">
              <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
            </button>
            {openFilterCol === 'status' && (
              <div className="absolute top-full mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1.5 animate-in zoom-in-95">
                {['All', 'Active Filing', 'Case-by-Case', 'Inactive (Temporary)'].map(opt => (
                  <button key={opt} onClick={() => { setClientStatusColFilter(opt); setOpenFilterCol(null); }} className={`w-full text-left px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-lg ${clientStatusColFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{opt}</button>
                ))}
              </div>
            )}
          </div>

          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400 text-right">Actions</div>
        </div>

        {/* DATA CONTAINER */}
        <div className="flex-1 overflow-auto no-scrollbar">
          {filteredClients.length === 0 ? (
            <div className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found</div>
          ) : (
            filteredClients.map((client, idx) => {
              const isExpanded = expandedRows.has(client.id);
              return (
                <div key={client.id} className="group border-b border-slate-50 last:border-0">
                  {/* MAIN ADAPTIVE ROW */}
                  <div className={`flex flex-col lg:grid ${gridTemplate} items-center bg-white hover:bg-indigo-50/30 transition-all duration-300 relative`}>

                    {/* S.No - Visible on Desktop, used for expand toggle on mobile */}
                    <div className="hidden lg:flex items-center p-4 text-[12px] font-black text-slate-300">
                      {(idx + 1).toString().padStart(2, '0')}
                    </div>

                    {/* Trade Name - STICKY FIRST COLUMN */}
                    <div className={`w-full lg:w-auto p-4 flex items-center justify-between lg:sticky lg:left-0 bg-inherit z-10 lg:border-r border-slate-100 lg:shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]`}>
                      <div className="flex items-center gap-3">
                        <button onClick={() => toggleRow(client.id)} className="lg:hidden h-8 w-8 flex items-center justify-center rounded-lg bg-slate-100 text-slate-400">
                          <svg className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                        </button>
                        <div>
                          <p className="text-[13px] font-black text-slate-900 uppercase break-words whitespace-normal leading-tight">{client.tradeName || client.legalName}</p>
                          <p className="lg:hidden text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">{client.gstProfile?.gstin}</p>
                        </div>
                      </div>
                      <div className="lg:hidden">
                        <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider ${
                          client.gstProfile?.gstStatus === 'Active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                        }`}>{client.gstProfile?.gstStatus}</span>
                      </div>
                    </div>

                    {/* GSTIN - Hidden on Mobile unless expanded */}
                    <div className="hidden lg:flex p-4 items-center gap-2">
                       <span className="text-[12px] font-black text-indigo-600 font-mono tracking-widest break-all">{client.gstProfile?.gstin}</span>
                    </div>

                    {/* GST Status - Hidden on Mobile */}
                    <div className="hidden lg:flex p-4 justify-center">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider whitespace-nowrap ${
                        client.gstProfile?.gstStatus === 'Active' ? 'bg-green-100 text-green-700' : 
                        client.gstProfile?.gstStatus === 'Suspended' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                      }`}>
                        {client.gstProfile?.gstStatus}
                      </span>
                    </div>

                    {/* Client Hub Status - Hidden on Mobile */}
                    <div className="hidden lg:flex p-4 justify-center">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider whitespace-nowrap ${
                        client.status === 'Active Filing' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                      }`}>
                        {client.status}
                      </span>
                    </div>

                    {/* Actions - Always Visible */}
                    <div className="w-full lg:w-auto p-4 flex items-center justify-end gap-2 shrink-0">
                      <button 
                        onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); setShowPassInView(false); setLocalPassValue(client.gstProfile?.password || ''); }}
                        className="h-9 w-9 lg:h-8 lg:w-8 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 flex items-center justify-center transition-all shadow-sm"
                      >
                        <svg className="h-5 w-5 lg:h-4 lg:w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                      </button>
                      <button 
                        onClick={() => setActiveMenuId(activeMenuId === client.id ? null : client.id)}
                        className="h-9 w-9 lg:h-8 lg:w-8 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-slate-900 flex items-center justify-center transition-all shadow-sm"
                      >
                        <svg className="h-5 w-5 lg:h-4 lg:w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 5v.01M12 12v.01M12 19v.01" /></svg>
                      </button>
                      {activeMenuId === client.id && (
                        <>
                          <div className="fixed inset-0 z-40" onClick={() => setActiveMenuId(null)} />
                          <div className="absolute right-4 mt-12 w-64 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-1.5 animate-in zoom-in-95">
                            <button onClick={() => { setSelectedClient(client); setTempPassword(client.gstProfile?.password || ''); setIsLoginModalOpen(true); setActiveMenuId(null); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-xl transition-colors">
                              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14" /></svg> Login Gateway
                            </button>
