          <div className="p-4 text-[13px] font-black uppercase text-slate-400 sticky left-0 bg-slate-50 border-r border-slate-100 z-10 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">Entity Identity</div>
