          <div className="p-4 text-[13px] font-black uppercase text-slate-400">Days Left</div>
          <div className="p-4 text-[13px] font-black uppercase text-slate-400 text-center">Status</div>
          <div className="p-4 text-[13px] font-black uppercase text-slate-400 text-right">View</div>
        </div>

        {/* DATA CONTAINER */}
        <div className="flex-1 overflow-auto no-scrollbar">
          {filteredRecords.length === 0 ? (
            <div className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No filed appeals documented</div>
          ) : (
            filteredRecords.map((rec, idx) => {
              const client = clients.find(c => c.id === rec.clientId);
              const hDays = getHearingDaysLeft(rec.hearingDate);
              const isExpanded = expandedRows.has(rec.id);
              return (
                <div key={rec.id} className="group border-b border-slate-50 last:border-0 transition-all">
                  <div className={`flex flex-col lg:grid ${gridTemplate} items-center bg-white hover:bg-indigo-50/20 transition-all duration-300 relative`}>

                    <div className="hidden lg:flex p-4 text-[12px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</div>

                    <div className="w-full lg:w-auto p-4 flex items-center justify-between lg:sticky lg:left-0 bg-inherit z-10 lg:border-r border-slate-100 lg:shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">
                      <div className="flex items-center gap-3">
                         <button onClick={() => toggleRow(rec.id)} className="lg:hidden h-8 w-8 rounded-lg bg-slate-100 text-slate-400 flex items-center justify-center">
                           <svg className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                         </button>
                         <div>
                            <p className="text-[12px] font-black text-slate-900 uppercase break-words whitespace-normal leading-tight">{rec.clientName}</p>
                            <p className="text-[9px] font-black text-indigo-600 font-mono tracking-widest mt-1">{client?.gstProfile?.gstin || 'N/A'}</p>
                         </div>
                      </div>
                      <div className="lg:hidden">
                         <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${hDays && hDays < 0 ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                           {hDays !== null ? (hDays < 0 ? 'Overdue' : `${hDays}d Left`) : 'No Date'}
                         </span>
                      </div>
                    </div>

                    <div className="hidden lg:flex p-4 text-[11px] font-black text-slate-700 uppercase break-all">{rec.referenceNo}</div>
                    <div className="hidden lg:flex p-4 text-[11px] font-black text-slate-500">{formatDisplayDate(rec.filedDate)}</div>

                    <div className="hidden lg:flex p-4">
                       <input type="date" value={rec.hearingDate || ''} onChange={(e) => updateHearingDate(rec.id, e.target.value)}
                         className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 text-[11px] font-black text-slate-900 outline-none focus:ring-2 focus:ring-indigo-600/10 transition-all" />
                    </div>

                    <div className="hidden lg:flex p-4">
                       {hDays !== null ? (
                         <span className={`text-[11px] font-black uppercase ${hDays < 0 ? 'text-red-500' : hDays <= 7 ? 'text-orange-500' : 'text-emerald-600'}`}>
                            {hDays < 0 ? `${Math.abs(hDays)} Overdue` : `${hDays} Days Left`}
                         </span>
                       ) : <span className="text-slate-300 font-black text-[10px] uppercase">Pending</span>}
                    </div>

                    <div className="hidden lg:flex p-4 justify-center relative">
                      <div className="w-full relative">
                        <button onClick={() => setActiveStatusMenuId(activeStatusMenuId === rec.id ? null : rec.id)}
                          className="w-full px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest bg-emerald-50 text-emerald-600 border border-emerald-100 flex items-center justify-between">
                          Filed <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                        </button>
                        {activeStatusMenuId === rec.id && (
                          <div className="absolute bottom-full mb-1 left-0 right-0 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                             <button onClick={() => updateRecordStatus(rec.id, 'Drop')} className="w-full px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-emerald-50 text-emerald-600 text-left">Relief Granted</button>
                             <button onClick={() => updateRecordStatus(rec.id, 'Demand')} className="w-full px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-red-50 text-red-600 text-left border-t border-slate-50">Sustained</button>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="w-full lg:w-auto p-4 flex justify-end">
                       <button onClick={() => { setViewingRecord(rec); setIsViewModalOpen(true); }} className="h-9 w-9 lg:h-8 lg:w-8 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 flex items-center justify-center shadow-sm">
                          <svg className="h-5 w-5 lg:h-4 lg:w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                       </button>
                    </div>
                  </div>

                  {/* ADAPTIVE MOBILE DETAIL CARD */}
                  {isExpanded && (
                    <div className="lg:hidden p-5 bg-slate-50 border-t border-slate-100 flex flex-col gap-6 animate-in slide-in-from-top-2">
                       <div className="grid grid-cols-2 gap-4">
                          <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Ref Number</p><p className="text-xs font-black text-slate-900 uppercase break-all">{rec.referenceNo}</p></div>
                          <div><p className="text-[10px] font-black uppercase text-slate-400 mb-1">Date Filed</p><p className="text-xs font-black text-slate-900">{formatDisplayDate(rec.filedDate)}</p></div>
                       </div>
                       <div>
                          <p className="text-[10px] font-black uppercase text-slate-400 mb-1">Set Hearing Date</p>
                          <input type="date" value={rec.hearingDate || ''} onChange={(e) => updateHearingDate(rec.id, e.target.value)}
                             className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-black text-slate-900 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" />
                       </div>
                       <div className="flex gap-3">
                          <button onClick={() => updateRecordStatus(rec.id, 'Drop')} className="flex-1 py-3 bg-emerald-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg">Relief Granted</button>
                          <button onClick={() => updateRecordStatus(rec.id, 'Demand')} className="flex-1 py-3 bg-red-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg">Demand Confirm</button>
                       </div>
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      </div>

      <NoticeForm isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSave} clients={clients} category="Appeal" initialData={selectedRecord} />
    </div>
  );
};

export default AppealFiled;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import Loader from '../../components/Loader';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
  onDataChange?: () => void;
}

const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All',
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());

  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const [tempPassword, setTempPassword] = useState('');
  const [showPassInView, setShowPassInView] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [localPassValue, setLocalPassValue] = useState('');
  const [showPassInLogin, setShowPassInLogin] = useState(false);
  const [isSavingPass, setIsSavingPass] = useState(false);

  const [gstStatusColFilter, setGstStatusColFilter] = useState<string>('All');
  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');
  const [openFilterCol, setOpenFilterCol] = useState<'gst' | 'status' | null>(null);

  const toggleRow = (id: string) => {
    setExpandedRows(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile) || []);
    } catch (error) {
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchClients(); }, []);

  const formatDate = (dateStr?: string) => {
    if (!dateStr || !dateStr.includes('-')) return dateStr || 'N/A';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  };

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];
    if (jurisdictionFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
      if (jurisdictionFilter === 'State' && sectorFilter !== 'All') list = list.filter(c => c.gstProfile?.sector === sectorFilter);
      if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') list = list.filter(c => c.gstProfile?.range === rangeFilter);
    }
    if (gstStatusColFilter !== 'All') list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
    if (clientStatusColFilter !== 'All') list = list.filter(c => c.status === clientStatusColFilter);

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleDataChange = () => {
    fetchClients();
    if (onDataChange) onDataChange();
  };

  const copyToClipboard = (text: string) => { navigator.clipboard.writeText(text); };
  const shareViaWhatsApp = (text: string) => { window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank'); };

  const handleUpdateGatewayPassword = async () => {
    if (!selectedClient) return;
    setIsSavingPass(true);
    try {
      const updatedClient = { ...selectedClient, gstProfile: { ...selectedClient.gstProfile!, password: tempPassword } };
      await mockBackend.saveClient(updatedClient);
      setSelectedClient(updatedClient);
      handleDataChange();
      setTimeout(() => setIsSavingPass(false), 800);
    } catch (err) { setIsSavingPass(false); }
  };

  const openPortalLogin = async (client: Client, finalPass?: string) => {
    if (finalPass && finalPass !== client.gstProfile?.password) {
      const updatedClient = { ...client, gstProfile: { ...client.gstProfile!, password: finalPass } };
      await mockBackend.saveClient(updatedClient);
      handleDataChange();
    }
    copyToClipboard(client.gstProfile?.username || '');
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  // Fix: Added missing handleEdit function to resolve the error on line 276
  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    setIsGstModalOpen(true);
    setIsDetailModalOpen(false);
  };

  // Added missing handleDelete function for detailed record removal
  const handleDelete = async (id: string) => {
    if (confirm('Delete this GST record from vault?')) {
      await mockBackend.deleteClient(id);
      setIsDetailModalOpen(false);
      handleDataChange();
    }
  };

  // Added missing saveQuickPasswordFromView function for inline password updates in the detail view
  const saveQuickPasswordFromView = async () => {
    if (!selectedClient || !selectedClient.gstProfile) return;
    const updatedClient = {
      ...selectedClient,
      gstProfile: { ...selectedClient.gstProfile, password: localPassValue }
    };
    await mockBackend.saveClient(updatedClient);
    setSelectedClient(updatedClient);
    setIsEditingPassword(false);
    handleDataChange();
  };

  const getCredText = (client: Client) => `*GST Credentials for ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n_Shared via Clientify_`;

  if (isLoading) return <Loader />;

  // DEFINING GRID TEMPLATE
  // S.No (4rem) | Trade Name (Sticky - min-200) | GSTIN (180px) | Statuses (140px each) | Actions (120px)
  const gridTemplate = "grid-cols-[4rem_minmax(12.5rem,1fr)_11.25rem_8.75rem_8.75rem_7.5rem]";

  return (
    <div className="flex flex-col h-full overflow-hidden animate-in fade-in duration-500">
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">

        {/* SIZE-ADAPTIVE HEADER */}
        <div className={`hidden lg:grid ${gridTemplate} bg-slate-50 border-b border-slate-100 z-20 sticky top-0`}>
          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400">S.No.</div>
          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400 sticky left-0 bg-slate-50 z-10 border-r border-slate-100 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]">Trade Name</div>
          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400">GSTIN</div>

          <div className="p-4 flex items-center justify-center gap-1.5 relative">
            <span className="text-[13px] font-black uppercase tracking-widest text-slate-400">GST Status</span>
            <button onClick={() => setOpenFilterCol(openFilterCol === 'gst' ? null : 'gst')} className="h-5 w-5 rounded bg-white border border-slate-200 text-slate-400 flex items-center justify-center shadow-sm">
              <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
            </button>
            {openFilterCol === 'gst' && (
              <div className="absolute top-full mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1.5 animate-in zoom-in-95">
                {['All', 'Active', 'Suspended', 'Cancelled'].map(opt => (
                  <button key={opt} onClick={() => { setGstStatusColFilter(opt); setOpenFilterCol(null); }} className={`w-full text-left px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-lg ${gstStatusColFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{opt}</button>
                ))}
              </div>
            )}
          </div>

          <div className="p-4 flex items-center justify-center gap-1.5 relative">
            <span className="text-[13px] font-black uppercase tracking-widest text-slate-400">Status</span>
            <button onClick={() => setOpenFilterCol(openFilterCol === 'status' ? null : 'status')} className="h-5 w-5 rounded bg-white border border-slate-200 text-slate-400 flex items-center justify-center shadow-sm">
              <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
            </button>
            {openFilterCol === 'status' && (
              <div className="absolute top-full mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1.5 animate-in zoom-in-95">
                {['All', 'Active Filing', 'Case-by-Case', 'Inactive (Temporary)'].map(opt => (
                  <button key={opt} onClick={() => { setClientStatusColFilter(opt); setOpenFilterCol(null); }} className={`w-full text-left px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-lg ${clientStatusColFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{opt}</button>
