              </div>
            )}
          </div>

          <div className="p-4 text-[13px] font-black uppercase tracking-widest text-slate-400 text-right">Actions</div>
        </div>

        {/* DATA CONTAINER */}
        <div className="flex-1 overflow-auto no-scrollbar">
          {filteredClients.length === 0 ? (
            <div className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found</div>
