                      }`}>
                        {client.gstProfile?.gstStatus}
                      </span>
                    </div>

                    {/* Client Hub Status - Hidden on Mobile */}
                    <div className="hidden lg:flex p-4 justify-center">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider whitespace-nowrap ${
                        client.status === 'Active Filing' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                      }`}>
