                       <div className="relative flex-1">
                          <input type={showPassInLogin ? "text" : "password"} value={tempPassword} onChange={e => setTempPassword(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-black text-slate-800 pr-12 outline-none focus:ring-4 focus:ring-indigo-50 transition-all" />
                          <button onClick={() => setShowPassInLogin(!showPassInLogin)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors">{showPassInLogin ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>}</button>
                       </div>
                       <button onClick={handleUpdateGatewayPassword} disabled={isSavingPass || tempPassword === selectedClient.gstProfile?.password}
                         className={`h-12 w-12 rounded-xl flex items-center justify-center transition-all ${isSavingPass ? 'bg-green-600 text-white' : tempPassword !== selectedClient.gstProfile?.password ? 'bg-indigo-600 text-white hover:bg-slate-900' : 'bg-slate-100 text-slate-300'}`}>
                          <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 13l4 4L19 7" /></svg>
                       </button>
                    </div>
                 </div>
              </div>
              <button onClick={() => { openPortalLogin(selectedClient, tempPassword); setIsLoginModalOpen(false); }}
                className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl hover:bg-slate-900 transition-all active:scale-95 flex items-center justify-center gap-3">
                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg> Login to GST Portal
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

export default GstMasterPortfolio;
